import { Activity, ArrowDownToLine, ArrowLeft, ArrowRight, BookOpen, Bookmark, BriefcaseBusiness, Check, CheckCheck, ChevronRight, CircleHelp, Clock, Cloud, Download, GraduationCap, HeartHandshake, House, Languages, LayoutDashboard, LogIn, LogOut, Menu, MessageCircle, Mic, MoreHorizontal, Play, Search, Send, Settings, ShieldCheck, Sparkles, Star, Target, TrendingUp, Wifi, WifiOff, X } from 'lucide-react';
import type { ActivityPoint } from '../components/ActivityCharts';
const WeeklyActivityChart = lazy(() => import('../components/ActivityCharts').then(module => ({ default: module.WeeklyActivityChart })));
const ProgressActivityChart = lazy(() => import('../components/ActivityCharts').then(module => ({ default: module.ProgressActivityChart })));
import { courses, lessons, scholarships, mentors } from '../data/mockData';
